                    ['term' => 'contoh-24', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Anyone** can join the club for free.', 'example_meaning' => 'Siapa pun bisa bergabung dengan klub itu secara gratis.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-25', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'They blamed **each other** for the mistake.', 'example_meaning' => 'Mereka saling menyalahkan atas kesalahan itu.', 'extra' => ['type' => 'example']],
