                    ['term' => 'contoh-1', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'The children **play** in the park every afternoon.', 'example_meaning' => 'Anak-anak bermain di taman setiap sore.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-2', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'This soup **tastes** delicious.', 'example_meaning' => 'Sup ini rasanya lezat.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-3', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She **is** studying for her exam right now.', 'example_meaning' => 'Dia sedang belajar untuk ujiannya sekarang.', 'extra' => ['type' => 'example']],
