            [
                'title' => 'Preposition (Kata Depan)',
                'level' => 'Elementary',
                'summary' => '*Preposition* adalah kata yang menunjukkan hubungan antara *noun*/*pronoun* dengan kata lain dalam kalimat, biasanya menyatakan waktu, tempat, atau arah. Preposition selalu diikuti oleh noun atau pronoun sebagai objeknya (*object of preposition*), tidak pernah diikuti verb dalam bentuk dasar.',
                'minutes' => 12,
                'xp' => 25,
                'content' => "<p>Preposition (kata depan) adalah kata yang menghubungkan noun atau pronoun dengan bagian lain dari kalimat untuk menunjukkan hubungan waktu, tempat, atau arah.</p>\n<table>\n<thead><tr><th>Jenis</th><th>Preposition umum</th><th>Contoh</th></tr></thead>\n<tbody>\n<tr><td>Time (waktu)</td><td>at, on, in</td><td>at 7 PM, on Monday, in July</td></tr>\n<tr><td>Place (tempat)</td><td>at, on, in, under, behind</td><td>at home, on the table, in the box</td></tr>\n<tr><td>Direction (arah)</td><td>to, into, from, through</td><td>go to school, walk into the room</td></tr>\n</tbody>\n</table>\n<p><strong>Catatan:</strong> Gunakan <strong>at</strong> untuk titik waktu/tempat spesifik (at 7 AM, at the station), <strong>on</strong> untuk hari/tanggal/permukaan (on Monday, on the table), dan <strong>in</strong> untuk periode waktu lebih panjang/ruang tertutup (in July, in the room).</p>",
                'items' => [
                    ['term' => 'Formula', 'reading' => null, 'romaji' => null, 'meaning' => 'menghubungkan noun/pronoun dengan kata lain untuk menunjukkan waktu (at/in/on), tempat (in/on/at/under), atau arah (to/into/from) — selalu diikuti noun atau pronoun', 'example' => null, 'example_meaning' => null, 'extra' => ['type' => 'formula', 'kind' => 'parts-of-speech']],
