            [
                'title' => 'Conjunction (Kata Sambung)',
                'level' => 'Elementary',
                'summary' => '*Conjunction* adalah kata yang menghubungkan kata, frasa, atau klausa dalam kalimat. *Coordinating conjunction* (FANBOYS: for, and, nor, but, or, yet, so) menghubungkan dua unsur yang setara, sedangkan *subordinating conjunction* (because, although, if, when) menghubungkan klausa utama dengan klausa anak.',
                'minutes' => 12,
                'xp' => 25,
                'content' => "<p>Conjunction (kata sambung) adalah kata yang menghubungkan kata, frasa, atau klausa agar kalimat menjadi lebih kompleks dan mengalir logis.</p>\n<table>\n<thead><tr><th>Jenis</th><th>Fungsi</th><th>Contoh</th></tr></thead>\n<tbody>\n<tr><td>Coordinating conjunction (FANBOYS)</td><td>Menghubungkan dua unsur yang setara/sejajar</td><td>for, and, nor, but, or, yet, so</td></tr>\n<tr><td>Subordinating conjunction</td><td>Menghubungkan klausa utama dengan klausa anak</td><td>because, although, since, if, when, while</td></tr>\n<tr><td>Correlative conjunction</td><td>Berpasangan untuk menghubungkan unsur setara</td><td>either...or, neither...nor, both...and</td></tr>\n</tbody>\n</table>\n<p><strong>Catatan:</strong> Berbeda dengan bahasa Indonesia, dalam bahasa Inggris satu pasangan konjungsi seperti \"although...but\" atau \"because...so\" TIDAK boleh dipakai bersamaan dalam satu kalimat untuk menghubungkan klausa yang sama.</p>",
                'items' => [
                    ['term' => 'Formula', 'reading' => null, 'romaji' => null, 'meaning' => 'menghubungkan kata/frasa/klausa — coordinating conjunction (FANBOYS) menghubungkan unsur setara, subordinating conjunction (because, although, if) menghubungkan klausa utama dan anak klausa', 'example' => null, 'example_meaning' => null, 'extra' => ['type' => 'formula', 'kind' => 'parts-of-speech']],
                    ['term' => 'contoh-1', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'I wanted to go for a walk, **but** it started raining.', 'example_meaning' => 'Saya ingin jalan-jalan, tetapi hujan mulai turun.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-2', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She stayed home **because** she felt sick.', 'example_meaning' => 'Dia tinggal di rumah karena dia merasa sakit.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-3', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Although** he studied hard, he failed the test.', 'example_meaning' => 'Meskipun dia belajar dengan giat, dia gagal dalam ujian.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-4', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'You can choose **either** tea **or** coffee.', 'example_meaning' => 'Kamu bisa memilih teh atau kopi.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-5', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'We will leave **as soon as** the rain stops.', 'example_meaning' => 'Kami akan berangkat segera setelah hujan berhenti.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-6', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'I like tea **and** coffee equally.', 'example_meaning' => 'Saya suka teh dan kopi sama-sama.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-7', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Since** you are here, let us start the meeting.', 'example_meaning' => 'Karena kamu sudah di sini, mari kita mulai rapatnya.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-8', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'He was tired, **yet** he kept working.', 'example_meaning' => 'Dia lelah, namun dia terus bekerja.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-9', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'We can go by car **or** by train.', 'example_meaning' => 'Kami bisa pergi naik mobil atau naik kereta.', 'extra' => ['type' => 'example']],
