                    ['term' => 'contoh-20', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'We stopped the game **because** it started to rain.', 'example_meaning' => 'Kami menghentikan permainan karena mulai turun hujan.', 'extra' => ['type' => 'example']],
