                    ['term' => 'contoh-22', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She was hungry, **so** she made a sandwich.', 'example_meaning' => 'Dia lapar, jadi dia membuat sandwich.', 'extra' => ['type' => 'example']],
