                    ['term' => 'contoh-24', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'He passed the test **because** he prepared well.', 'example_meaning' => 'Dia lulus ujian karena dia mempersiapkan diri dengan baik.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-25', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'I like neither the color **nor** the design.', 'example_meaning' => 'Saya tidak suka warnanya maupun desainnya.', 'extra' => ['type' => 'example']],
