                    ['term' => 'Although she was tired, but she kept working.', 'reading' => null, 'romaji' => null, 'meaning' => 'Although she was tired, she kept working.', 'example' => 'Dalam bahasa Inggris, "although" dan "but" tidak boleh dipakai bersamaan dalam satu kalimat karena keduanya sama-sama berfungsi sebagai konjungsi untuk klausa yang sama (berbeda dengan bahasa Indonesia "meskipun...tetapi...").', 'extra' => ['type' => 'mistake']],
                    ['term' => 'Because it was raining, so we stayed home.', 'reading' => null, 'romaji' => null, 'meaning' => 'Because it was raining, we stayed home.', 'example' => 'Sama seperti kasus "although...but", konjungsi "because" dan "so" tidak boleh dipakai bersamaan untuk menghubungkan sebab-akibat yang sama dalam satu kalimat.', 'extra' => ['type' => 'mistake']],
