                    ['term' => 'contoh-8', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Ugh**, this traffic is unbearable.', 'example_meaning' => 'Uh, kemacetan ini tidak tertahankan.', 'extra' => ['type' => 'example']],
