            [
                'title' => 'Complex Sentence (Kalimat Kompleks)',
                'level' => 'Upper-Intermediate',
                'summary' => '*Complex sentence* terdiri dari satu *independent clause* dan satu atau lebih *dependent clause* yang dihubungkan dengan *subordinating conjunction* seperti because, although, when, if, atau since. Berbeda dari compound sentence, dependent clause tidak bisa berdiri sendiri karena maknanya bergantung pada klausa utama.',
                'minutes' => 15,
                'xp' => 30,
                'content' => "<p>Dependent clause dalam complex sentence memiliki subjek dan kata kerja, tetapi tidak membentuk pikiran yang lengkap tanpa independent clause. Posisinya bisa di awal atau di akhir kalimat.</p>\n<ul>\n<li><strong>Alasan:</strong> because, since, as.</li>\n<li><strong>Waktu:</strong> when, while, before, after, until, as soon as.</li>\n<li><strong>Syarat:</strong> if, unless, provided that.</li>\n<li><strong>Kontras:</strong> although, though, even though, whereas.</li>\n</ul>\n<p><strong>Aturan koma:</strong> Subordinating Conjunction + Dependent Clause, + Independent Clause (jika dependent clause di awal) ATAU Independent Clause + Subordinating Conjunction + Dependent Clause (tanpa koma, jika di akhir).</p>",
                'items' => [
                    ['term' => 'Formula', 'reading' => null, 'romaji' => null, 'meaning' => 'Independent Clause + Subordinating Conjunction + Dependent Clause (atau dibalik dengan koma)', 'example' => null, 'example_meaning' => null, 'extra' => ['type' => 'formula', 'kind' => 'structure']],
                    ['term' => 'contoh-1', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'I stayed home **because** I was sick.', 'example_meaning' => 'Saya tinggal di rumah karena saya sakit.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-2', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Although** he studied hard, he failed the test.', 'example_meaning' => 'Meskipun dia belajar dengan giat, dia gagal dalam ujian.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-3', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She will call you **when** she arrives.', 'example_meaning' => 'Dia akan meneleponmu ketika dia tiba.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-4', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => "We can't leave **unless** everyone is ready.", 'example_meaning' => 'Kami tidak bisa pergi kecuali semua orang sudah siap.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-5', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She was late **because** her car broke down.', 'example_meaning' => 'Dia terlambat karena mobilnya mogok.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-6', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Since** it was raining, we canceled the picnic.', 'example_meaning' => 'Karena hujan turun, kami membatalkan piknik.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-7', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'I will help you **if** you ask me nicely.', 'example_meaning' => 'Saya akan membantumu jika kamu memintanya dengan sopan.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-8', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'He kept working **although** he was very tired.', 'example_meaning' => 'Dia terus bekerja meskipun dia sangat lelah.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-9', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**After** she finished her studies, she moved abroad.', 'example_meaning' => 'Setelah dia menyelesaikan studinya, dia pindah ke luar negeri.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-10', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'You should call her **before** you visit.', 'example_meaning' => 'Kamu sebaiknya meneleponnya sebelum kamu berkunjung.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-11', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**While** he was cooking, his phone rang.', 'example_meaning' => 'Sementara dia sedang memasak, teleponnya berdering.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-12', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'They stayed inside **because** it was too cold outside.', 'example_meaning' => 'Mereka tetap di dalam karena terlalu dingin di luar.', 'extra' => ['type' => 'example']],
