                    ['term' => 'contoh-15', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**As** the sun set, the sky turned orange.', 'example_meaning' => 'Ketika matahari terbenam, langit berubah menjadi oranye.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-16', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'I will not leave **until** you arrive.', 'example_meaning' => 'Saya tidak akan pergi sampai kamu tiba.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-17', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'He locked the door **before** he left the house.', 'example_meaning' => 'Dia mengunci pintu sebelum dia meninggalkan rumah.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-18', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Whenever** she feels stressed, she listens to music.', 'example_meaning' => 'Setiap kali dia merasa stres, dia mendengarkan musik.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-19', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'The trip was canceled **because** of the storm.', 'example_meaning' => 'Perjalanan itu dibatalkan karena badai.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-20', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Though** he apologized, she was still upset.', 'example_meaning' => 'Meskipun dia meminta maaf, dia masih kesal.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-21', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'We will start the meeting **as soon as** everyone arrives.', 'example_meaning' => 'Kami akan memulai rapat segera setelah semua orang tiba.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-22', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She smiled **when** she saw the surprise.', 'example_meaning' => 'Dia tersenyum ketika dia melihat kejutan itu.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-23', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**Before** you leave, please turn off the lights.', 'example_meaning' => 'Sebelum kamu pergi, tolong matikan lampunya.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-24', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'He cannot drive **since** he lost his license.', 'example_meaning' => 'Dia tidak bisa menyetir sejak dia kehilangan SIM-nya.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-25', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => '**If** the weather improves, we will go camping.', 'example_meaning' => 'Jika cuacanya membaik, kami akan pergi berkemah.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-26', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She kept smiling **although** she was in pain.', 'example_meaning' => 'Dia terus tersenyum meskipun dia kesakitan.', 'extra' => ['type' => 'example']],
                    ['term' => 'Although he studied hard, but he failed the test.', 'reading' => null, 'romaji' => null, 'meaning' => 'Although he studied hard, he failed the test.', 'example' => '"Although" dan "but" tidak boleh digunakan bersamaan dalam satu kalimat karena keduanya sama-sama kata sambung kontras; cukup gunakan salah satu.', 'extra' => ['type' => 'mistake']],
                    ['term' => 'Because I was sick I stayed home.', 'reading' => null, 'romaji' => null, 'meaning' => 'Because I was sick, I stayed home.', 'example' => 'Ketika dependent clause diletakkan di awal kalimat, wajib diikuti tanda koma sebelum independent clause.', 'extra' => ['type' => 'mistake']],
