                    ['term' => 'contoh-12', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'She **will be** upset if you **forget** her birthday.', 'example_meaning' => 'Dia akan kesal jika kamu melupakan ulang tahunnya.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-13', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If it **is** sunny tomorrow, we **will have** a picnic.', 'example_meaning' => 'Jika besok cerah, kami akan berpiknik.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-14', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If you **arrive** late, the manager **will notice**.', 'example_meaning' => 'Jika kamu datang terlambat, manajer akan menyadarinya.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-15', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If I **won** the lottery, I **would buy** a big house.', 'example_meaning' => 'Jika saya memenangkan lotre, saya akan membeli rumah besar.', 'extra' => ['type' => 'example']],
