                    ['term' => 'contoh-17', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If I **were** you, I **would accept** the offer.', 'example_meaning' => 'Jika saya menjadi kamu, saya akan menerima tawaran itu.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-18', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If they **lived** closer, we **would meet** more often.', 'example_meaning' => 'Jika mereka tinggal lebih dekat, kami akan bertemu lebih sering.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-19', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If ice **is** left in the sun, it **melts** quickly.', 'example_meaning' => 'Jika es ditinggalkan di bawah sinar matahari, es itu cepat mencair.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-20', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If you **do not water** the plants, they **wilt**.', 'example_meaning' => 'Jika kamu tidak menyiram tanaman, tanaman itu layu.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-21', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If she **had** more time, she **would learn** to paint.', 'example_meaning' => 'Jika dia punya lebih banyak waktu, dia akan belajar melukis.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-22', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If you **freeze** water, it **turns** into ice.', 'example_meaning' => 'Jika kamu membekukan air, air itu berubah menjadi es.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-23', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'Iron **rusts** if it **is exposed** to moisture.', 'example_meaning' => 'Besi berkarat jika terkena kelembapan.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-24', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If we **leave** now, we **will catch** the early train.', 'example_meaning' => 'Jika kami berangkat sekarang, kami akan mengejar kereta pagi.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-25', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If she **calls**, I **will let** you know immediately.', 'example_meaning' => 'Jika dia menelepon, saya akan segera memberitahumu.', 'extra' => ['type' => 'example']],
                    ['term' => 'contoh-26', 'reading' => null, 'romaji' => null, 'meaning' => null, 'example' => 'If I **had** wings, I **would fly** across the ocean.', 'example_meaning' => 'Jika saya punya sayap, saya akan terbang melintasi lautan.', 'extra' => ['type' => 'example']],
                    ['term' => 'If I will have time, I will help you.', 'reading' => null, 'romaji' => null, 'meaning' => 'If I have time, I will help you.', 'example' => 'Klausa "if" pada Conditional Type 1 menggunakan Simple Present (V1), bukan "will", meskipun main clause menggunakan "will".', 'extra' => ['type' => 'mistake']],
                    ['term' => 'If I was you, I would accept the offer.', 'reading' => null, 'romaji' => null, 'meaning' => 'If I were you, I would accept the offer.', 'example' => 'Pada Conditional Type 2, gunakan "were" untuk semua subjek (termasuk I/he/she/it) sebagai bentuk subjunctive, bukan "was".', 'extra' => ['type' => 'mistake']],
                    ['term' => 'If it rain, the ground gets wet.', 'reading' => null, 'romaji' => null, 'meaning' => 'If it rains, the ground gets wet.', 'example' => 'Conditional Type 0 menggunakan Simple Present di kedua klausa; subjek tunggal (it) memerlukan tambahan -s pada kata kerja.', 'extra' => ['type' => 'mistake']],
                ],
